const BG={office:['🏢','#E3F2FD','#BBDEFB','Văn phòng'],class:['🏫','#FFF8E1','#FFE0B2','Lớp học'],campus:['🌳','#E8F5E9','#C8E6C9','Sân trường'],cafe:['☕','#EFEBE9','#D7CCC8','Quán cà phê'],phone:['📱','#EDE7F6','#D1C4E9','Gọi điện thoại'],library:['📚','#E0F7FA','#B2EBF2','Thư viện'],home:['🏠','#FFF3E0','#FFE0B2','Ở nhà'],kitchen:['🍳','#FBE9E7','#FFCCBC','Nhà bếp'],canteen:['🍱','#F1F8E9','#DCEDC8','Căng tin'],shop:['🛍️','#FCE4EC','#F8BBD0','Cửa hàng'],market:['🍎','#FFFDE7','#FFF59D','Chợ hoa quả'],mall:['🏬','#F3E5F5','#E1BEE7','Trung tâm mua sắm'],street:['🚕','#ECEFF1','#CFD8DC','Trên đường'],restaurant:['🍽️','#FFF3E0','#FFCC80','Nhà hàng'],hospital:['🏥','#E0F2F1','#B2DFDB','Bệnh viện'],airport:['✈️','#E1F5FE','#B3E5FC','Sân bay'],hotel:['🏨','#FFF8E1','#FFECB3','Khách sạn'],park:['🌸','#F1F8E9','#C5E1A5','Công viên']};
function scene(t){
  const b=BG[t.bg]||BG.class,who=[...new Set(t.l.map(l=>l[0]))];
  const W=360,H=150,n=who.length,step=Math.min(96,(W-40)/n),x0=(W-step*n)/2;
  const ppl=who.map((k,i)=>{const x=x0+i*step+step/2-38;return `<g transform='translate(${x} 34)'>${av(k,76).replace("<svg class='hb-av'",`<svg x='0' y='0'`)}</g><text x='${x+38}' y='${H-6}' text-anchor='middle' font-size='11' fill='#4E342E' font-family='Nunito,sans-serif' font-weight='700'>${esc(CH[k].vi)}</text>`;}).join('');
  const ph=t.bg==='phone'&&n===2?`<g transform='translate(${W/2-9} 58)'><rect width='18' height='30' rx='4' fill='#37474F'/><rect x='2.5' y='4' width='13' height='20' rx='1.5' fill='#80DEEA'/></g><path d='M${W/2-34} 66 q8 -8 16 0 M${W/2+18} 66 q8 -8 16 0' stroke='#7E57C2' stroke-width='2' fill='none'/>`:'';
  return `<svg class='hb-scene' viewBox='0 0 ${W} ${H}' role='img' aria-label='${esc(b[3])}'><defs><linearGradient id='g${t.bg}' x1='0' y1='0' x2='0' y2='1'><stop offset='0' stop-color='${b[1]}'/><stop offset='1' stop-color='${b[2]}'/></linearGradient></defs><rect width='${W}' height='${H}' rx='14' fill='url(#g${t.bg})'/><rect y='${H-34}' width='${W}' height='34' fill='rgba(255,255,255,.35)'/><text x='16' y='34' font-size='26'>${b[0]}</text><text x='${W-14}' y='24' text-anchor='end' font-size='12' fill='#6D4C41' font-family='Nunito,sans-serif' font-weight='700'>${esc(b[3])}</text>${ph}${ppl}</svg>`;
}
/* ---------- giọng đọc theo vai ---------- */
const VO={f:{p:1.08},m:{p:.82,male:1},c:{p:1.3},k:{p:1.45,r:.95},p:{p:1.4,r:.95},x:{p:1.15}};
let SLOW=false,PLAY=null;
function sayZh(text,who,done){
  try{
    const ss=window.speechSynthesis;if(!ss){done&&setTimeout(done,600);return;}
    const u=new SpeechSynthesisUtterance(text.replace(/[“”]/g,''));u.lang='zh-CN';
    const g=VO[(CH[who]||{}).g]||{p:1.05};
    if(g.male&&window.hhMale){const m=hhMale();if(m)u._v=m;else u._p=.8;}
    u._p=u._p||g.p;u._r=SLOW?.6:(g.r||.85);
    let fin=false;const end=()=>{if(fin)return;fin=true;done&&done();};
    u.onend=end;u.onerror=end;setTimeout(end,1500+text.length*(SLOW?550:380));
    ss.speak(u);
  }catch(e){done&&done();}
}
function stopAll(){PLAY=null;try{speechSynthesis.cancel();}catch(e){}document.querySelectorAll('#hb2 .hb-ln.on').forEach(x=>x.classList.remove('on','me'));document.querySelectorAll('#hb2 .hb-pa').forEach(b=>b.textContent='▶ Nghe cả bài');}
