function vocab(l){
  const row=(w,i)=>`<div class='hb-w'><span class='hb-i'>${i}</span><button type='button' class='hb-z han' onclick='hb2W(this)' data-z='${esc(w[0])}'>${w[0]}</button><div class='hb-m'><b>${w[1]}</b>${w[2]?` <i>${w[2]}</i>`:''}<br>${esc(w[3])}</div><button type='button' class='hb-sp' onclick='hb2W(this)' data-z='${esc(w[0])}' title='Nghe'>🔊</button>${/^[\u4e00-\u9fff]+$/.test(w[0])?`<button type='button' class='hb-sp' title='Tập viết' onclick='hb2Write("${w[0]}")'>✍️</button>`:''}</div>`;
  return `<div class='card'><div class='hb-bar'><b>📝 Từ mới · ${l.w.length} từ</b><span><button type='button' class='btn ghost hb-pa' onclick='hb2AllW(this)'>▶ Nghe tất cả</button> <label class='hb-ck'><input type='checkbox' ${SLOW?'checked':''} onchange='hb2Slow(this.checked)'> 🐢 Đọc chậm</label></span></div>
  <p class='hb-tip'>Bấm vào chữ Hán hoặc 🔊 để nghe. Bấm ✍️ để tập viết từng chữ.</p>${l.w.map((w,i)=>row(w,i+1)).join('')}
  ${l.p.length?`<h4 style='margin:14px 0 6px'>Tên riêng</h4>${l.p.map((w,i)=>row(w,i+1)).join('')}`:''}</div>`;
}
window.hb2W=b=>sayZh(b.dataset.z,'wang');
window.hb2Write=z=>{try{go('butthuan');pad(z,1);}catch(e){}};
window.hb2Slow=v=>{SLOW=v;document.querySelectorAll('#hb2 .hb-ck input').forEach(x=>x.checked=v);};
window.hb2AllW=function(b){
  if(PLAY){stopAll();return;}
  const l=L.find(x=>x.n===CUR),ws=l.w.concat(l.p),rows=[...document.querySelectorAll('#hb2Body .hb-w')];let i=0;const tok=PLAY={};b.textContent='■ Dừng';
  const nx=()=>{if(PLAY!==tok)return;rows.forEach(r=>r.classList.remove('on'));if(i>=ws.length){stopAll();return;}rows[i].classList.add('on');rows[i].scrollIntoView({block:'nearest'});sayZh(ws[i][0],'wang',()=>setTimeout(nx,500));i++;};nx();
};
